RUN awk '/handle /electric/\* \{/{p=1; print "  handle /electric/* {
    header Content-Type application/json
    header electric-handle stub
    header electric-offset 0_0
    header electric-cursor 0
    header electric-schema `{"id":{"type":"text"}}`
    header electric-up-to-date true
    header Access-Control-Allow-Origin *
    header Access-Control-Expose-Headers "electric-handle, electric-offset, electric-cursor, electric-schema, electric-up-to-date, content-type, cache-control, x-txid"

    @subset query subset__where=*
    handle @subset {
      respond `{"metadata":{"xmin":"1","xmax":"1","xip_list":[],"snapshot_mark":0,"database_lsn":"0"},"data":[]}` 200
    }
    handle {
      respond `[{"headers":{"control":"up-to-date"}}]` 200
    }
  }"; next} p && /^  \}/{p=0; next} !p{print}' /etc/caddy/Caddyfile > /etc/caddy/Caddyfile.tmp && mv /etc/caddy/Caddyfile.tmp /etc/caddy/Caddyfile

unix-socket-forward.pre:
if [ -n "$DOCKER_HOST" ] && [ ! -e /var/run/docker.sock ]; then
  ulimit -n 1048576 2>/dev/null || true
  addr=${DOCKER_HOST#tcp://}
  [ -n "$addr" ] || { echo "bkid: DOCKER_HOST=$DOCKER_HOST has no tcp:// address" >&2; exit 1; }
  socat -d0 -t 86400 UNIX-LISTEN:/var/run/docker.sock,fork,backlog=1024,reuseaddr "TCP:$addr,keepalive,keepidle=30,keepintvl=15,keepcnt=4" &
  SOCAT_PID=$!
  trap 'kill $SOCAT_PID 2>/dev/null || true' EXIT INT TERM
  socat -u OPEN:/dev/null UNIX-CONNECT:/var/run/docker.sock,retry=20,interval=0.2 >/dev/null 2>&1 \
    || { echo "bkid: socat bridge to /var/run/docker.sock not ready" >&2; exit 1; }
fi

