COPY <<'TIMERS' /timer-check.sql
DO $$ BEGIN
  IF EXISTS (SELECT FROM hybrid_truco_match.instance i
    WHERE i.state->>'phase' IN ('playing', 'wager', 'brink', 'envido') AND (i.state->>'deadline')::bigint > 0
      AND NOT EXISTS (SELECT FROM public.schedule s WHERE s.emits_entity = 'machine_timer_tick'
        AND s.emits_values @> jsonb_build_object('machine', 'truco_match', 'row', jsonb_build_object('id', i.id::text)))) THEN
    RAISE EXCEPTION 'machine truco_match has instances waiting on a deadline the ticker was never given';
  END IF;
END $$;
DO $$ BEGIN
  IF EXISTS (SELECT FROM hybrid_truco_presence.instance i
    WHERE i.state->>'phase' IN ('visible') AND (i.state->>'until')::bigint > 0
      AND NOT EXISTS (SELECT FROM public.schedule s WHERE s.emits_entity = 'machine_timer_tick'
        AND s.emits_values @> jsonb_build_object('machine', 'truco_presence', 'row', jsonb_build_object('id', i.id::text)))) THEN
    RAISE EXCEPTION 'machine truco_presence has instances waiting on a deadline the ticker was never given';
  END IF;
END $$;
DO $$ BEGIN
  IF EXISTS (SELECT FROM hybrid_truco_challenge.instance i
    WHERE i.state->>'phase' IN ('offered') AND (i.state->>'deadline')::bigint > 0
      AND NOT EXISTS (SELECT FROM public.schedule s WHERE s.emits_entity = 'machine_timer_tick'
        AND s.emits_values @> jsonb_build_object('machine', 'truco_challenge', 'row', jsonb_build_object('id', i.id::text)))) THEN
    RAISE EXCEPTION 'machine truco_challenge has instances waiting on a deadline the ticker was never given';
  END IF;
END $$;
DO $$ BEGIN
  IF EXISTS (SELECT FROM hybrid_truco_call.instance i
    WHERE i.state->>'phase' IN ('offered') AND (i.state->>'deadline')::bigint > 0
      AND NOT EXISTS (SELECT FROM public.schedule s WHERE s.emits_entity = 'machine_timer_tick'
        AND s.emits_values @> jsonb_build_object('machine', 'truco_call', 'row', jsonb_build_object('id', i.id::text)))) THEN
    RAISE EXCEPTION 'machine truco_call has instances waiting on a deadline the ticker was never given';
  END IF;
END $$;
TIMERS

